def bound_existing_shifts(apps, schema_editor):
    Assignment = apps.get_model('accounts', 'GateAssignment')
    for assignment in Assignment.objects.select_related('event').iterator():
        assignment.starts_at = assignment.event.start_at - timedelta(hours=2)
        assignment.ends_at = min(assignment.event.end_at or assignment.event.start_at + timedelta(hours=12),
                                 assignment.starts_at + timedelta(hours=24))
        if assignment.ends_at <= assignment.starts_at:
            assignment.ends_at = assignment.starts_at + timedelta(hours=12)
        assignment.save(update_fields=['starts_at', 'ends_at'])


